static LayerPinSpec parse_layer_pin_spec(const nlohmann::json& j) {
    if (j.is_string()) {
        std::string s = j.get<std::string>();
        if (s != "all")
            throw std::runtime_error("layer_pin_spec string must be \"all\", got: " + s);
        return s;
    }
    if (j.is_array()) {
        std::vector<int> v;
        for (const auto& el : j) v.push_back(el.get<int>());
        return v;
    }
    throw std::runtime_error("layer_pin_spec must be \"all\" or array of integers");
}

static nlohmann::json layer_pin_spec_to_json(const LayerPinSpec& spec) {
    if (std::holds_alternative<std::string>(spec)) return std::get<std::string>(spec);
    return std::get<std::vector<int>>(spec);
}

static AutoOrInt parse_auto_or_int(const nlohmann::json& j) {
    if (j.is_string()) {
        std::string s = j.get<std::string>();
        if (s != "auto")
            throw std::runtime_error("auto_or_int string must be \"auto\", got: " + s);
        return s;
    }
    if (j.is_number_integer()) return j.get<int>();
    throw std::runtime_error("auto_or_int must be \"auto\" or a positive integer");
}

static nlohmann::json auto_or_int_to_json(const AutoOrInt& v) {
    if (std::holds_alternative<std::string>(v)) return std::get<std::string>(v);
    return std::get<int>(v);
}

