static VramAllocationConfig parse_vram_allocation(const nlohmann::json& j) {
    VramAllocationConfig r;
    if (j.contains("resident")) r.resident = j.at("resident").is_null() ? double(0.0) : j.at("resident").get<double>();
    if (j.contains("expert_streaming")) r.expert_streaming = j.at("expert_streaming").is_null() ? double(0.0) : j.at("expert_streaming").get<double>();
    if (j.contains("stable_zone_fraction")) r.stable_zone_fraction = j.at("stable_zone_fraction").is_null() ? double(-1.0) : j.at("stable_zone_fraction").get<double>();
    if (j.contains("safety_margin_gb")) r.safety_margin_gb = j.at("safety_margin_gb").is_null() ? double(-1.0) : j.at("safety_margin_gb").get<double>();
    return r;
}

static nlohmann::json vram_allocation_to_json(const VramAllocationConfig& r) {
    nlohmann::json j;
    j["resident"] = r.resident <= 0.0 ? nlohmann::json(nullptr) : nlohmann::json(r.resident);
    j["expert_streaming"] = r.expert_streaming <= 0.0 ? nlohmann::json(nullptr) : nlohmann::json(r.expert_streaming);
    j["stable_zone_fraction"] = r.stable_zone_fraction <= 0.0 ? nlohmann::json(nullptr) : nlohmann::json(r.stable_zone_fraction);
    j["safety_margin_gb"] = r.safety_margin_gb <= 0.0 ? nlohmann::json(nullptr) : nlohmann::json(r.safety_margin_gb);
    return j;
}

static GpuConfig parse_gpu(const nlohmann::json& j) {
    GpuConfig r;
    r.id = j.at("id").get<int>();
    r.type = parse_gpu_type(j.at("type").get<std::string>());
    r.vram_gb = j.at("vram_gb").is_null() ? double(0.0) : j.at("vram_gb").get<double>();
    if (j.contains("pcie_gen")) r.pcie_gen = j.at("pcie_gen").is_null() ? int(0) : j.at("pcie_gen").get<int>();
    if (j.contains("pcie_width")) r.pcie_width = j.at("pcie_width").is_null() ? int(0) : j.at("pcie_width").get<int>();
    if (j.contains("numa_node")) r.numa_node = j.at("numa_node").is_null() ? int(-1) : j.at("numa_node").get<int>();
    r.pcie_bandwidth_loss_ratio = get_or(j, "pcie_bandwidth_loss_ratio", 0.85);
    if (j.contains("compute_weight") && !j.at("compute_weight").is_null()) r.compute_weight = j.at("compute_weight").get<double>();
    if (j.contains("vram_budget_gb")) r.vram_budget_gb = j.at("vram_budget_gb").is_null() ? int(0) : j.at("vram_budget_gb").get<int>();
    if (j.contains("roles") && !j.at("roles").is_null()) {
        r.roles.clear();
        for (const auto& el : j.at("roles")) r.roles.push_back(parse_gpu_role(el.get<std::string>()));
    }
    if (j.contains("vram_allocation_gb") && !j.at("vram_allocation_gb").is_null()) r.vram_allocation_gb = parse_vram_allocation(j.at("vram_allocation_gb"));
    return r;
}

static nlohmann::json gpu_to_json(const GpuConfig& r) {
    nlohmann::json j;
    j["id"] = r.id;
    j["type"] = to_string(r.type);
    j["vram_gb"] = r.vram_gb <= 0.0 ? nlohmann::json(nullptr) : nlohmann::json(r.vram_gb);
    j["pcie_gen"] = r.pcie_gen == 0 ? nlohmann::json(nullptr) : nlohmann::json(r.pcie_gen);
    j["pcie_width"] = r.pcie_width == 0 ? nlohmann::json(nullptr) : nlohmann::json(r.pcie_width);
    j["numa_node"] = r.numa_node < 0 ? nlohmann::json(nullptr) : nlohmann::json(r.numa_node);
    j["pcie_bandwidth_loss_ratio"] = r.pcie_bandwidth_loss_ratio;
    j["compute_weight"] = r.compute_weight ? nlohmann::json(*r.compute_weight) : nlohmann::json(nullptr);
    j["vram_budget_gb"] = r.vram_budget_gb == 0 ? nlohmann::json(nullptr) : nlohmann::json(r.vram_budget_gb);
    { nlohmann::json arr = nlohmann::json::array(); for (const auto& el : r.roles) arr.push_back(to_string(el)); j["roles"] = arr; }
    if (r.vram_allocation_gb) j["vram_allocation_gb"] = vram_allocation_to_json(*r.vram_allocation_gb); else j["vram_allocation_gb"] = nullptr;
    return j;
}

