    if (j.contains("beta_fast") && !j.at("beta_fast").is_null()) r.beta_fast = j.at("beta_fast").get<double>();
    if (j.contains("beta_slow") && !j.at("beta_slow").is_null()) r.beta_slow = j.at("beta_slow").get<double>();
