static HardwareConfig parse_hardware(const nlohmann::json& j) {
    HardwareConfig r;
    for (const auto& el : j.at("gpus")) r.gpus.push_back(parse_gpu(el));
    if (j.contains("cpu_expert_devices")) {
        for (const auto& el : j.at("cpu_expert_devices")) r.cpu_expert_devices.push_back(parse_cpu_expert(el));
    }
    if (j.contains("tp_array") && !j.at("tp_array").is_null()) {
        r.tp_array.clear();
        for (const auto& el : j.at("tp_array")) r.tp_array.push_back(el.get<int>());
    }
    r.system_ram_gb = j.at("system_ram_gb").is_null() ? int(0) : j.at("system_ram_gb").get<int>();
    if (j.contains("nvme_paths") && !j.at("nvme_paths").is_null()) {
        r.nvme_paths.clear();
        for (const auto& el : j.at("nvme_paths")) r.nvme_paths.push_back(el.get<std::string>());
    }
    if (j.contains("nvme_capacity_gb") && !j.at("nvme_capacity_gb").is_null()) r.nvme_capacity_gb = j.at("nvme_capacity_gb").get<int>();
    if (j.contains("dcp_indexer_mode")) r.dcp_indexer_mode = parse_dcp_indexer_mode(j.at("dcp_indexer_mode").get<std::string>());
    if (j.contains("dcp_kv_mode")) r.dcp_kv_mode = parse_dcp_kv_mode(j.at("dcp_kv_mode").get<std::string>());
    return r;
}

static nlohmann::json hardware_to_json(const HardwareConfig& r) {
    nlohmann::json j;
    { nlohmann::json arr = nlohmann::json::array(); for (const auto& el : r.gpus) arr.push_back(gpu_to_json(el)); j["gpus"] = arr; }
    { nlohmann::json arr = nlohmann::json::array(); for (const auto& el : r.cpu_expert_devices) arr.push_back(cpu_expert_to_json(el)); j["cpu_expert_devices"] = arr; }
    j["tp_array"] = r.tp_array.empty() ? nlohmann::json(nullptr) : nlohmann::json(r.tp_array);
    j["system_ram_gb"] = r.system_ram_gb == 0 ? nlohmann::json(nullptr) : nlohmann::json(r.system_ram_gb);
    j["nvme_paths"] = r.nvme_paths;
    j["nvme_capacity_gb"] = r.nvme_capacity_gb ? nlohmann::json(*r.nvme_capacity_gb) : nlohmann::json(nullptr);
    j["dcp_indexer_mode"] = to_string(r.dcp_indexer_mode);
    j["dcp_kv_mode"] = to_string(r.dcp_kv_mode);
    return j;
}

static PinnedLayersConfig parse_pinned_layers(const nlohmann::json& j) {
    PinnedLayersConfig r;
    if (j.contains("attention")) r.attention = parse_layer_pin_spec(j.at("attention"));
    if (j.contains("dense_ffn_layers") && !j.at("dense_ffn_layers").is_null()) {
        r.dense_ffn_layers.clear();
        for (const auto& el : j.at("dense_ffn_layers")) r.dense_ffn_layers.push_back(el.get<int>());
    }
    r.embedding = get_or(j, "embedding", true);
    r.output_head = get_or(j, "output_head", true);
    if (j.contains("gating")) r.gating = parse_layer_pin_spec(j.at("gating"));
    return r;
}

