static KvCacheConfig parse_kv_cache(const nlohmann::json& j) {
    KvCacheConfig r;
    if (j.contains("max_pages_per_gpu")) r.max_pages_per_gpu = parse_auto_or_int(j.at("max_pages_per_gpu"));
    r.page_size_tokens = get_or(j, "page_size_tokens", 16);
    r.speculation_pool_fraction = get_or(j, "speculation_pool_fraction", 0.15);
    r.indexer_k_page_size_tokens = get_or(j, "indexer_k_page_size_tokens", 8192);
    r.prefill_scratch_preallocated_gb = get_or(j, "prefill_scratch_preallocated_gb", 0.5);
    r.streaming_spill_fraction = get_or(j, "streaming_spill_fraction", 0.34);
    r.dcp_chunk_size = get_or(j, "dcp_chunk_size", 16);
    if (j.contains("naive_prefill_context_ceiling") && !j.at("naive_prefill_context_ceiling").is_null()) r.naive_prefill_context_ceiling = j.at("naive_prefill_context_ceiling").get<int>();
    r.page_growth_chunk_tokens = get_or(j, "page_growth_chunk_tokens", 1024);
    if (j.contains("_advanced")) r._advanced = parse_kv_cache_advanced(j.at("_advanced"));
    return r;
}

