    j["dcp_chunk_size"] = r.dcp_chunk_size;
    j["naive_prefill_context_ceiling"] = r.naive_prefill_context_ceiling ? nlohmann::json(*r.naive_prefill_context_ceiling) : nlohmann::json(nullptr);
    j["page_growth_chunk_tokens"] = r.page_growth_chunk_tokens;
    j["_advanced"] = kv_cache_advanced_to_json(r._advanced);
