static ExpertCacheConfig parse_expert_cache(const nlohmann::json& j) {
    ExpertCacheConfig r;
    if (j.contains("eviction_policy")) r.eviction_policy = parse_eviction_policy(j.at("eviction_policy").get<std::string>());
    r.eviction_alpha_recency = get_or(j, "eviction_alpha_recency", 0.4);
    r.eviction_beta_frequency = get_or(j, "eviction_beta_frequency", 0.35);
    r.eviction_gamma_routing_weight = get_or(j, "eviction_gamma_routing_weight", 0.25);
    r.eviction_delta_temporal_autocorr = get_or(j, "eviction_delta_temporal_autocorr", 0.0);
    r.eviction_epsilon_coactivation = get_or(j, "eviction_epsilon_coactivation", 0.0);
    r.eviction_zeta_prefetch_score = get_or(j, "eviction_zeta_prefetch_score", 0.0);
    r.eviction_eta_hysteresis = get_or(j, "eviction_eta_hysteresis", 0.0);
    r.hysteresis_enabled = get_or(j, "hysteresis_enabled", false);
    r.hysteresis_stages = get_or(j, "hysteresis_stages", 5);
    r.hysteresis_up_threshold = get_or(j, "hysteresis_up_threshold", 5);
    r.hysteresis_down_threshold = get_or(j, "hysteresis_down_threshold", 1);
    r.duplication_frequency_threshold_percentile = get_or(j, "duplication_frequency_threshold_percentile", 95);
    r.temporal_autocorrelation_bonus = get_or(j, "temporal_autocorrelation_bonus", 0.8);
    r.stable_zone_fraction = get_or(j, "stable_zone_fraction", 0.7);
    r.inclusive_cache = get_or(j, "inclusive_cache", true);
    if (j.contains("_advanced")) r._advanced = parse_expert_cache_advanced(j.at("_advanced"));
    return r;
}

