static MemoryConfig parse_memory(const nlohmann::json& j) {
    MemoryConfig r;
    if (j.contains("pinned_layers")) r.pinned_layers = parse_pinned_layers(j.at("pinned_layers"));
    if (j.contains("tp_mode_per_layer")) r.tp_mode_per_layer = parse_tp_mode_per_layer(j.at("tp_mode_per_layer"));
    if (j.contains("kv_cache")) r.kv_cache = parse_kv_cache(j.at("kv_cache"));
    if (j.contains("kv_tiering")) r.kv_tiering = parse_kv_tiering(j.at("kv_tiering"));
    if (j.contains("expert_cache")) r.expert_cache = parse_expert_cache(j.at("expert_cache"));
    if (j.contains("nvme_tier")) r.nvme_tier = parse_nvme_tier(j.at("nvme_tier"));
    if (j.contains("numa")) r.numa = parse_numa(j.at("numa"));
    r.vram_safety_margin_gb = get_or(j, "vram_safety_margin_gb", 1.0);
    r.host_packed_cache_mb = get_or(j, "host_packed_cache_mb", 0);
    r.preload_expert_buffers = get_or(j, "preload_expert_buffers", true);
    r.pin_host_expert_pool = get_or(j, "pin_host_expert_pool", true);
    if (j.contains("pin_host_expert_pool_sizing")) r.pin_host_expert_pool_sizing = parse_pin_host_expert_pool_sizing(j.at("pin_host_expert_pool_sizing"));
    r.pin_host_expert_pool_extra_scratch_bytes = get_or(j, "pin_host_expert_pool_extra_scratch_bytes", 0);
    r.pin_host_expert_pool_preload = get_or(j, "pin_host_expert_pool_preload", true);
    if (j.contains("cross_node_spill")) r.cross_node_spill = parse_cross_node_spill(j.at("cross_node_spill"));
    if (j.contains("pin_host_expert_pool_direct_load") && !j.at("pin_host_expert_pool_direct_load").is_null()) r.pin_host_expert_pool_direct_load = j.at("pin_host_expert_pool_direct_load").get<bool>();
    r.pin_host_expert_pool_direct_o_direct = get_or(j, "pin_host_expert_pool_direct_o_direct", true);
    r.pin_host_expert_pool_iouring = get_or(j, "pin_host_expert_pool_iouring", false);
    r.pin_host_expert_pool_thp = get_or(j, "pin_host_expert_pool_thp", true);
    if (j.contains("arena_attach")) r.arena_attach = parse_arena_attach(j.at("arena_attach"));
    if (j.contains("arena_placement")) r.arena_placement = parse_arena_placement(j.at("arena_placement"));
    return r;
}

static nlohmann::json memory_to_json(const MemoryConfig& r) {
    nlohmann::json j;
    j["pinned_layers"] = pinned_layers_to_json(r.pinned_layers);
    j["tp_mode_per_layer"] = tp_mode_per_layer_to_json(r.tp_mode_per_layer);
    j["kv_cache"] = kv_cache_to_json(r.kv_cache);
    j["kv_tiering"] = kv_tiering_to_json(r.kv_tiering);
    j["expert_cache"] = expert_cache_to_json(r.expert_cache);
    j["nvme_tier"] = nvme_tier_to_json(r.nvme_tier);
    j["numa"] = numa_to_json(r.numa);
    j["vram_safety_margin_gb"] = r.vram_safety_margin_gb;
    j["host_packed_cache_mb"] = r.host_packed_cache_mb;
    j["preload_expert_buffers"] = r.preload_expert_buffers;
    j["pin_host_expert_pool"] = r.pin_host_expert_pool;
    j["pin_host_expert_pool_sizing"] = pin_host_expert_pool_sizing_to_json(r.pin_host_expert_pool_sizing);
    j["pin_host_expert_pool_extra_scratch_bytes"] = r.pin_host_expert_pool_extra_scratch_bytes;
    j["pin_host_expert_pool_preload"] = r.pin_host_expert_pool_preload;
    j["cross_node_spill"] = cross_node_spill_to_json(r.cross_node_spill);
    j["pin_host_expert_pool_direct_load"] = r.pin_host_expert_pool_direct_load ? nlohmann::json(*r.pin_host_expert_pool_direct_load) : nlohmann::json(nullptr);
    j["pin_host_expert_pool_direct_o_direct"] = r.pin_host_expert_pool_direct_o_direct;
    j["pin_host_expert_pool_iouring"] = r.pin_host_expert_pool_iouring;
    j["pin_host_expert_pool_thp"] = r.pin_host_expert_pool_thp;
    j["arena_attach"] = arena_attach_to_json(r.arena_attach);
    j["arena_placement"] = arena_placement_to_json(r.arena_placement);
    return j;
}

