    r.draft_context_capacity_tokens = get_or(j, "draft_context_capacity_tokens", 8192);
    r.aux_capture_max_rows = get_or(j, "aux_capture_max_rows", 2048);
    r.epm_dump_dir = get_or(j, "epm_dump_dir", std::string{""});
